    sqInt arg;
    sqInt argumentArray;
    sqInt arraySize;
    usqInt ccIndex;
    sqInt delta;
    sqInt header;
    sqInt index;
    sqInt offset;
    sqInt performArgCount;
    usqInt savedNewMethod;
    sqInt selector;
