    sqInt class;
    sqInt classFormat;
    sqInt contextSize;
    sqInt firstField;
    usqInt fmt;
    sqInt header;
    sqInt i;
    sqInt lastField;
    sqInt numFields;
    usqInt numLiterals;
    int oopGone;
    sqInt sp;
    usqInt weakOop;

