		headerSqInt = longAt((void *)(newFreeChunk));
		szUsqInt = (headerSqInt & TypeMask
					? headerSqInt & SizeMask
					: (longAt((void *)(newFreeChunk - (BytesPerWord * 2)))) & LongSizeMask);
