    usqInt ccIndex;
    sqInt class;
    sqInt classFormat;
    sqInt deltaBytes;
    sqInt desiredLength;
    sqInt fixedFields;
    usqInt fmt;
    sqInt hdr;
    sqInt indexableFields;
