    usqInt ccIndex;
    sqInt child;
    sqInt childType;
    sqInt class;
    sqInt classFormat;
    sqInt contextSize;
    sqInt field;
    usqInt fmt;
    sqInt header;
    sqInt header1;
    sqInt header2;
    sqInt headerSqInt;
    sqInt headerSqIntSqInt;
    sqInt lastFieldOffset;
    sqInt lastFieldOffsetSqInt;
    usqInt numLiterals;
    sqInt numOops;
    sqInt parentField;
    sqInt sp;
    sqInt statMarkCountLocal;
    sqInt sz;
    sqInt type;
    usqInt typeBits;
    sqInt typeSqInt;
