		headerSqInt = longAt((void *)(oop));
		type = /* rightType: */
				(headerSqInt & SizeMask
					? (headerSqInt & CompactClassMask
							? HeaderTypeShort
							: HeaderTypeClass)
					: HeaderTypeSizeAndClass);
