					/* who we worked on below */
					child = field;

					/* where to put it */
					field = parentField;
					parentField = longAt((void *)(field));
					longAtput((void *)(field),child);

					/* point at header */
					field -= BytesPerWord;
					action = StartField;
					goto l2;
