		assert(fwdBlockValid(fwdBlockUsqInt));
		realHeader = longAt((void *)(fwdBlockUsqInt + BytesPerWord));

		/* following code is like sizeBitsOf: */
		if (realHeader & TypeMask) {
			sz = realHeader & SizeMask;
		}
		else {
			sz = (longAt((void *)(oop - (BytesPerWord * 2)))) & LongSizeMask;
		}
		oop = (oop + sz) + (headerTypeBytes[(longAt((void *)(oop + sz))) & TypeMask]);
		/* end objectAfterWhileForwarding: */
