    sqInt bytecodesPerLine;
    usqInt ccIndex;
    char *className;
    sqInt classOop;
    sqInt cls;
    sqInt column;
    usqInt fmt;
    sqInt fmtSqInt;
    sqInt header;
    sqInt index;
    sqInt isFloatInstanceRV;
    sqInt lastIndex;
    sqInt length;
